from pathlib import Path
import importlib.util,json,subprocess,sys,tempfile
R=Path.cwd();sys.path.insert(0,str(R/'tests/semantics'));spec=importlib.util.spec_from_file_location('retained_source_compiler',R/'.tools/magic-publication/source_compiler.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);m.ROOT=R;m.SOURCE_CASES=[];m.LINES=[];m.ACCESS_CASES=[]
out=Path(tempfile.mkdtemp(prefix='compiler-failure-flow-',dir=R/'.tools'));original_run=subprocess.run;original_retain=m.retain_failure;paths=[];records=[]
def retain(*args):
 path=original_retain(*args);paths.append(path);return path
m.retain_failure=retain
for mode in ['timeout','false','nonzero']:
 def run(command,*args,**kwargs):
  if len(command)>2 and command[1]=='dune':return subprocess.CompletedProcess(command,0)
  if Path(command[0]).name=='numeric_runner.exe':
   assert kwargs['timeout']==600
   if mode=='timeout':raise subprocess.TimeoutExpired(command,600,output=b'\xff',stderr=b'\xfe')
   return subprocess.CompletedProcess(command,0 if mode=='false' else 2,stdout='false\n',stderr='controlled\n')
  return original_run(command,*args,**kwargs)
 subprocess.run=run
 try:m.main()
 except AssertionError as error:
  path=paths[-1];data=json.loads((path/'results.json').read_text());assert not Path(data['command'][-1]).exists();assert (path/'cases.watsup').is_file();assert len(data['records'])==2
  if mode=='timeout':assert data['result']['stdout_base64']=='/w==' and data['result']['stderr_base64']=='/g=='
  records.append({'mode':mode,'error':repr(error),'artifact':str(path),'native_records':len(data['records'])})
 else:raise AssertionError('controlled failure was accepted')
 finally:subprocess.run=original_run
assert len(set(paths))==3
(out/'results.json').write_text(json.dumps({'scope':'Three controlled aggregate-tool failures through actual compiler main, real native/checked setup, no aggregate semantic execution or source agreement claim. Exact artifacts survive TemporaryDirectory cleanup.','records':records},indent=2)+'\n');print(out,'3 flow controls pass')

